{
  "metric": "avg_total_amount",
  "target_window": "2025-01-20",
  "baseline_window": "2025-01-06, 2025-01-13, 2025-01-27",
  "hypotheses": [
    {
      "id": "H0",
      "kind": "metric",
      "statement": "Average total amount per yellow taxi trip on Monday 2025-01-20 was higher than the average of the other three Mondays in January 2025 (2025-01-06, 2025-01-13, 2025-01-27).",
      "support_if": "avg_total_amount on 2025-01-20 > mean(avg_total_amount on 2025-01-06, 2025-01-13, 2025-01-27) by a meaningful margin (e.g., >5%).",
      "refute_if": "avg_total_amount on 2025-01-20 is within normal variance of the other three Mondays (e.g., <5% difference)."
    },
    {
      "id": "H1",
      "kind": "holiday",
      "statement": "Monday 2025-01-20 was Martin Luther King Jr. Day (federal holiday), which altered demand composition (e.g., more leisure/airport trips, fewer commuter trips) and raised average fare.",
      "support_if": "us_holidays shows a federal holiday on 2025-01-20 (MLK Day) and no federal holiday on the other three Mondays; trip count on 2025-01-20 differs significantly from baseline Mondays.",
      "refute_if": "2025-01-20 is not a federal holiday, or trip count and fare patterns are similar to baseline Mondays."
    },
    {
      "id": "H2",
      "kind": "weather",
      "statement": "Adverse weather on 2025-01-20 (e.g., snow, low temperature, precipitation) increased fares via longer trips, surge-like conditions, or shift to taxi from other modes.",
      "support_if": "nyc_weather_daily shows snow_mm > 0 or prcp_mm > 5 or tmax_c < 0 on 2025-01-20, while baseline Mondays had milder conditions.",
      "refute_if": "Weather on 2025-01-20 was similar to or better than baseline Mondays (no snow, low precipitation, comparable temperatures)."
    },
    {
      "id": "H3",
      "kind": "fare_mix",
      "statement": "The fare mix shifted on 2025-01-20 toward higher-fare trip types (e.g., longer distances, airport trips, tolls) compared to baseline Mondays.",
      "support_if": "avg_trip_distance on 2025-01-20 is significantly higher than baseline Mondays, and/or trip count distribution by distance bands (if available) shows more long trips.",
      "refute_if": "avg_trip_distance on 2025-01-20 is similar to or lower than baseline Mondays."
    },
    {
      "id": "H4",
      "kind": "zone_mix",
      "statement": "Pickup/drop-off zone mix shifted on 2025-01-20 (e.g., more airport/Manhattan core trips) increasing average fare, but daily aggregates lack zone detail so this is a proxy via distance/fare correlation.",
      "support_if": "avg_trip_distance and avg_total_amount both spike together on 2025-01-20, suggesting longer/higher-fare zones; zone-level data would confirm but not available in daily aggregate.",
      "refute_if": "avg_trip_distance does not increase with avg_total_amount, weakening zone-mix explanation."
    },
    {
      "id": "H5",
      "kind": "data_quality",
      "statement": "Data quality issue on 2025-01-20 (e.g., missing trips, duplicate records, fare calculation errors) artificially inflated avg_total_amount.",
      "support_if": "Trip count on 2025-01-20 is anomalously low/high vs baseline Mondays, or avg_total_amount is an extreme outlier (>3 std dev from baseline mean).",
      "refute_if": "Trip count and avg_total_amount on 2025-01-20 are within normal ranges of baseline Mondays; no obvious data anomalies."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Get avg_total_amount, trips, avg_trip_distance for target Monday 2025-01-20 and baseline Mondays 2025-01-06, 2025-01-13, 2025-01-27 from whybot.yellow_daily.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Check if 2025-01-20 is a federal holiday (MLK Day) and baseline Mondays are not, via LEFT JOIN whybot.us_holidays on trip_date for the four Mondays.",
      "tables": ["whybot.yellow_daily", "whybot.us_holidays"]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Get weather (prcp_mm, snow_mm, tmax_c, tmin_c) for 2025-01-20 and baseline Mondays from whybot.nyc_weather_daily.",
      "tables": ["whybot.nyc_weather_daily"]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Compare avg_trip_distance on 2025-01-20 vs baseline Mondays from whybot.yellow_daily to test fare_mix via distance proxy.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Jointly examine avg_total_amount and avg_trip_distance on 2025-01-20 vs baseline Mondays to assess zone_mix proxy (correlation of fare and distance).",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H5",
      "purpose": "Assess data quality: check trip count volatility and avg_total_amount outlier status on 2025-01-20 vs baseline Mondays from whybot.yellow_daily.",
      "tables": ["whybot.yellow_daily"]
    }
  ],
  "rationale": "First iteration: quantify the metric jump (H0) and test 5 competing hypotheses (holiday, weather, fare_mix via distance, zone_mix via distance-fare correlation, data_quality) using only daily aggregates. All queries use allowed tables and date window. Holiday check uses authoritative us_holidays. Weather uses Central Park NOAA. Fare/zone mix proxied by avg_trip_distance since zone-level not in daily aggregate. Data quality checked via trip count and outlier detection."
}

{
  "sql": "SELECT y.trip_date, y.avg_total_amount, h.holiday_name, d.d_day_name, CASE WHEN h.holiday_name IS NOT NULL THEN 'holiday' ELSE 'regular' END AS day_type FROM whybot.yellow_daily y LEFT JOIN whybot.us_holidays h ON h.holiday_date = y.trip_date JOIN whybot.date_dim d ON d.d_date = y.trip_date WHERE y.trip_date IN (DATE '2025-01-13', DATE '2025-01-20', DATE '2025-01-27') AND d.d_day_name = 'Monday' ORDER BY y.trip_date",
  "tables_used": ["whybot.yellow_daily", "whybot.us_holidays", "whybot.date_dim"],
  "note": "Compares avg_total_amount for the four Mondays in Jan 2025, highlighting 2025-01-20 as MLK federal holiday if holiday_name appears"
}

