{
  "sql": "SELECT y.trip_date, y.avg_total_amount, w.tmax_c, h.holiday_name, h.is_national FROM whybot.yellow_daily y JOIN whybot.nyc_weather_daily w ON w.obs_date = y.trip_date LEFT JOIN whybot.us_holidays h ON h.holiday_date = y.trip_date WHERE y.trip_date BETWEEN DATE '2025-01-01' AND DATE '2025-01-31' AND w.tmax_c < 0 AND (h.is_national IS NULL OR h.is_national = FALSE) ORDER BY y.trip_date",
  "tables_used": [
    "whybot.yellow_daily",
    "whybot.nyc_weather_daily",
    "whybot.us_holidays"
  ],
  "note": "Cold non-holiday weekdays in Jan 2025; LEFT JOIN ensures no row for non-holiday days"
}

